@startuml
class OOBank {
}

class Branch {
  +address : string
  +branchNumber : int
}

class Division {
}

class Subdivision {
}

class Employee {
}

class Client {
}

class Account {
  +accountNumber : string
  +balance : double
  +creditOrOverdraftLimit : double
  +interestRate : float
  +monthlyFee : float
  +privileges : string[]
}

class MortgageAccount extends Account {
  +property : string
}

class CheckingAccount extends Account {
}

class CreditCardAccount extends Account {
  +expiryDate : date
  +secondaryCards : string[]
}

class Manager {
}

Employee <|-- Manager

OOBank "1" -- "*" Division : has
OOBank "1" -- "*" Subdivision : has
Division "1" -- "*" Subdivision : has
Subdivision "1" -- "*" Branch : has
Branch "1" -- "*" Account : offers
Client "1..*" -- "*" Account : owns
Client "0..*" -- "0..1" Employee : personal banker

Division "1" -- "1" Manager : managed by
Division "1" -- "*" Employee : has
@enduml

